"use client";
import { cn } from "@/lib/utils";

import { useState } from "react";
import { ElasticIndicator } from "@/lib/takt-indicator";

export function SegmentedControl({
  className,
  options = ["Day", "Week", "Month"],
  onChange,
}: {
  className?: string;
  options?: string[];
  onChange?: (index: number) => void;
}) {
  const [requested, setIndex] = useState(0);
  const index = Math.min(requested, Math.max(0, options.length - 1));
  if (!options.length) return null;
  return (
    <div className={cn("grid gap-3", className)}>
      <div
        role="group"
        aria-label="Period"
        className="relative flex items-center rounded-2xl border border-foreground/10 bg-muted p-1"
      >
        <span aria-hidden className="absolute inset-1 rounded-[inherit]">
          <ElasticIndicator
            count={options.length}
            index={index}
            className="border border-foreground/10 bg-card shadow-sm"
          />
        </span>
        {options.map((opt, i) => (
          <button
            key={opt}
            type="button"
            aria-pressed={i === index}
            onClick={() => {
              setIndex(i);
              onChange?.(i);
            }}
            className="relative min-h-9 flex-1 cursor-pointer rounded-xl px-4 text-xs font-medium"
          >
            <span
              className={
                i === index
                  ? "relative text-primary"
                  : "relative text-foreground/75"
              }
            >
              {opt}
            </span>
          </button>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useLayoutEffect, useRef } from "react";

// The advancing edge reaches its stop before the trailing edge catches up.
export function ElasticIndicator({
  index,
  count,
  className = "bg-primary",
}: {
  index: number;
  count: number;
  className?: string;
}) {
  const pill = useRef<HTMLSpanElement>(null);
  const previous = useRef(index);
  useLayoutEffect(() => {
    const node = pill.current;
    if (!node || !count) return;
    const slot = Math.min(count - 1, Math.max(0, index));
    node.style.transitionDuration =
      slot >= previous.current ? "370ms, 190ms" : "190ms, 370ms";
    node.style.left = (100 * slot) / count + "%";
    node.style.right = (100 * (count - slot - 1)) / count + "%";
    previous.current = slot;
  }, [index, count]);
  return count > 0 ? (
    <span
      aria-hidden
      ref={pill}
      className={
        "pointer-events-none absolute inset-y-0 rounded-[inherit] ease-[cubic-bezier(.19,1,.32,1)] motion-safe:transition-[left,right] motion-reduce:transition-none! motion-reduce:duration-0! " +
        className
      }
    />
  ) : null;
}
